SINA_SMART["physio1-gastric-secretion"] = {"lecture":"physio1-gastric-secretion","title":"Gastric secretion","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-gastric-secretion:e0","text":"Parietal cells: HCl and intrinsic factor. Chief cells: pepsinogen and lipase.","topic":"Cells and what they secrete","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-gastric-secretion:e1","text":"G cells (antrum): gastrin. D cells: somatostatin. ECL cells: histamine.","topic":"Cells and what they secrete","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-gastric-secretion:e2","text":"H⁺/K⁺ ATPase pumps H⁺ out for K⁺; HCO₃⁻ goes to blood (alkaline tide).","topic":"How HCl is made","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-gastric-secretion:e3","text":"Acid concentration is constant (~150 mM); the rate varies.","topic":"How HCl is made","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-gastric-secretion:e7","text":"Intrinsic factor + B12 absorbed in the terminal ileum; loss → pernicious anaemia.","topic":"Roles of the secretions","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-gastric-secretion:e4","text":"ACh (M3), gastrin (CCK2), histamine (H2) potentiate each other.","topic":"Regulation and phases","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-gastric-secretion:e5","text":"Somatostatin (antral pH < 3) inhibits gastrin: negative feedback.","topic":"Regulation and phases","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-gastric-secretion:e6","text":"Phases: cephalic ~30%, gastric ~60%, intestinal mainly inhibitory.","topic":"Regulation and phases","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-gastric-secretion:e8","text":"Mucus depends on prostaglandins: NSAIDs cause ulcers.","topic":"Clinical applications","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-gastric-secretion:e9","text":"Zollinger-Ellison: gastrinoma → hyperacidity and multiple ulcers.","topic":"Clinical applications","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"867tcf":"a","3uxv37":"a","1k04zsw":"a","1updgil":"a","te572q":"a","q0nwi4":"a","1xf3bau":"a","2mj5vp":"a","vurdf9":"a","zn7h09":"a","18dcfys":"a","9iun6":"a","zunfdv":"a","16etgqx":"a","1pcwu11":"a","vyxqw3":"a","1ccalgh":"a","1egp5fa":"x"},"mapCounts":{"verified":0,"auto":17,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-gastric-secretion:e0":{"s":0,"u":["Parietal cells: HCl and intrinsic factor. Chief cells: pepsinogen and lipase.","In the body and fundus : parietal cells (HCl and intrinsic factor), chief cells (pepsinogen and gastric lipase), mucous neck cells, and ECL cells (histamine).","In the antrum : G cells (gastrin), D cells (somatostatin) and mucous cells."],"dp":[]},"physio1-gastric-secretion:e1":{"s":0,"u":["G cells (antrum): gastrin. D cells: somatostatin. ECL cells: histamine.","In the antrum : G cells (gastrin), D cells (somatostatin) and mucous cells.","In the body and fundus : parietal cells (HCl and intrinsic factor), chief cells (pepsinogen and gastric lipase), mucous neck cells, and ECL cells (histamine)."],"dp":[]},"physio1-gastric-secretion:e2":{"s":1,"u":["H⁺/K⁺ ATPase pumps H⁺ out for K⁺; HCO₃⁻ goes to blood (alkaline tide).","The HCO₃⁻ goes to the blood: the alkaline tide after a meal.","The H⁺/K⁺ ATPase (proton pump) on the apical membrane pumps H⁺ into the lumen in exchange for K⁺."],"dp":[{"h":"Why PPIs work better than H2 blockers","t":"H2 antagonists remove only one of the three stimulants; gastrin and acetylcholine can still drive the pump, especially after a meal. Proton pump inhibitors block the H⁺/K⁺ ATPase itself, the final common step, so acid falls whatever the stimulus. They bind irreversibly to active pumps, which is why they are taken 30 minutes before breakfast, when pumps are about to be switched on, and why their effect lasts until new pumps are made."}]},"physio1-gastric-secretion:e3":{"s":1,"u":["Acid concentration is constant (~150 mM); the rate varies.","The concentration stays constant (150-160 mM); what varies is the rate."],"dp":[]},"physio1-gastric-secretion:e7":{"s":2,"u":["Intrinsic factor + B12 absorbed in the terminal ileum; loss → pernicious anaemia.","Intrinsic factor : a glycoprotein that binds vitamin B12 ; the complex is absorbed in the terminal ileum .","Its loss causes pernicious (Biermer's) anaemia , with achlorhydria and gastric atrophy."],"dp":[]},"physio1-gastric-secretion:e4":{"s":3,"u":["ACh (M3), gastrin (CCK2), histamine (H2) potentiate each other.","Three stimulants act together and potentiate each other: acetylcholine (M3, Ca²⁺ pathway), gastrin (CCK2, Ca²⁺) and histamine (H2, cAMP)."],"dp":[]},"physio1-gastric-secretion:e5":{"s":3,"u":["Somatostatin (antral pH < 3) inhibits gastrin: negative feedback.","The brake is somatostatin from D cells, released when antral pH falls below about 3; prostaglandins also inhibit."],"dp":[]},"physio1-gastric-secretion:e6":{"s":3,"u":["Phases: cephalic ~30%, gastric ~60%, intestinal mainly inhibitory.","Intestinal phase : mostly inhibitory; acid, fat and hyperosmolar chyme in the duodenum release secretin, somatostatin and GIP , which switch acid off.","Cephalic phase (~30%): sight, smell, taste, via the vagus."],"dp":[]},"physio1-gastric-secretion:e8":{"s":4,"u":["Mucus depends on prostaglandins: NSAIDs cause ulcers.","Peptic ulcer results from an imbalance between aggression (acid, pepsin, H. pylori , NSAIDs) and defence (mucus, bicarbonate, prostaglandins, blood flow).","Zollinger-Ellison syndrome : a gastrin-secreting tumour (gastrinoma) causes massive acid output and multiple, diffuse ulcers."],"dp":[]},"physio1-gastric-secretion:e9":{"s":4,"u":["Zollinger-Ellison: gastrinoma → hyperacidity and multiple ulcers.","Zollinger-Ellison syndrome : a gastrin-secreting tumour (gastrinoma) causes massive acid output and multiple, diffuse ulcers."],"dp":[]}},"meta":{"867tcf":{"a":"recall","vg":"physio1-gastric-secretion:e0/recall/1"},"3uxv37":{"a":"recall","vg":"physio1-gastric-secretion:e0/recall/1"},"1k04zsw":{"a":"recall","vg":"physio1-gastric-secretion:e1/recall/1"},"1updgil":{"a":"recall","vg":"physio1-gastric-secretion:e2/recall/1"},"te572q":{"a":"recall","vg":"physio1-gastric-secretion:e2/recall/2"},"q0nwi4":{"a":"recall","vg":"physio1-gastric-secretion:e1/recall/2"},"1xf3bau":{"a":"recall","vg":"physio1-gastric-secretion:e0/recall/2"},"2mj5vp":{"a":"recall","vg":"physio1-gastric-secretion:e5/recall/1"},"vurdf9":{"a":"recall","vg":"physio1-gastric-secretion:e6/recall/1"},"zn7h09":{"a":"recall","vg":"physio1-gastric-secretion:e7/recall/1"},"18dcfys":{"a":"recall","vg":"physio1-gastric-secretion:e8/recall/1"},"9iun6":{"a":"recall","vg":"physio1-gastric-secretion:e2/recall/3"},"zunfdv":{"a":"relationship","vg":"physio1-gastric-secretion:e9/relationship/1"},"16etgqx":{"a":"recall","vg":"physio1-gastric-secretion:e3/recall/1"},"1pcwu11":{"a":"recall","vg":"physio1-gastric-secretion:e0/recall/3"},"vyxqw3":{"a":"recall","vg":"physio1-gastric-secretion:e1/recall/3"},"1ccalgh":{"a":"recall","vg":"physio1-gastric-secretion:e6/recall/2"}},"explRev":"daa773c2a92b"};
